var body = $input.first().json.body || {};
var project = body.project || 'candlekeep/candlekeep-frontend';
var container = body.container || 'candlekeep-frontend-frontend-1';
var targetFile = body.targetFile || '';
var method = body.method || '';
var insertAfter = body.insertAfter || null;
var systemPrompt = body.systemPrompt || 'You are a senior Vue 3 / Nuxt / TypeScript engineer working in this exact codebase (Pinia Options-API stores). Follow the existing code style precisely. Output ONLY the action method source code, as a plain object-method (name(args) { ... } or async name(args) { ... }) - no function keyword, no arrow function, no surrounding actions/defineStore wrapper, no markdown fences, no explanation.';
var taskDescription = body.taskDescription || '';
return [{ json: {
  project: project,
  container: container,
  targetFile: targetFile,
  method: method,
  insertAfter: insertAfter,
  systemPrompt: systemPrompt,
  taskDescription: taskDescription
} }];

var msg = $input.first().json.message;
var raw = (msg && msg.content) ? msg.content : '';
var cleaned = raw.replace(/^```[a-zA-Z]*\n?/, '').replace(/```\s*$/, '').trim();
var method = $('Normalize Input').first().json.method;
var nameEscaped = method.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
var pattern = new RegExp('^(async\\s+)?' + nameEscaped + '\\s*\\(');
var valid = pattern.test(cleaned);
return [{ json: {
  methodBody: cleaned,
  valid: valid,
  reason: valid ? null : "qwen response did not start with '" + method + "(' (or 'async " + method + "(') after stripping markdown fences"
} }];

// Échappement shell : une valeur venant de la requête ne doit jamais sortir de ses apostrophes
function shq(s) { return "'" + String(s).replace(/'/g, "'\''") + "'"; }
var AST_PATCH_SRC = "#!/usr/bin/env node
'use strict';

// ast_patch_ts.cjs — insert or replace a single Pinia store action (a method
// inside defineStore(...)'s `actions: { ... }` object literal) in an
// existing TypeScript file, without touching anything else in it.
//
// Design: locate-and-splice, mirroring ast_patch_ruby.rb exactly — the
// TypeScript compiler API is used only to find the exact source range of
// the target action (or, on insert, the last existing action to anchor
// after); the rest of the file is never reprinted, so formatting/comments
// elsewhere never move. .cjs extension forces CommonJS regardless of the
// host package.json's "type": "module".
//
// Scope (v1): Options-API Pinia stores only — defineStore('id', { state,
// getters, actions: {...} }) — not the setup-function store style, and not
// <script setup> component functions. See llm-specialists' hybrid-dev-loop
// skill for why this scope was chosen.
//
// Usage:
//   node ast_patch_ts.cjs --file app/stores/application.ts --method setLocale \
//     --body /tmp/new_action.ts [--insert-after otherAction] [--write]
//
// Output (stdout, JSON, always):
//   success: {"ok":true,"action":"replaced"|"inserted","method":"name","content":"<full patched file>"}
//   failure: {"ok":false,"error":"..."}
// Exit code 0 on success, 1 on usage/lookup error, 2 on a patch that would
// produce invalid TypeScript (caught before anything is written).

const ts = require('typescript');
const fs = require('fs');

function parseArgs(argv) {
  const args = { write: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--file') args.file = argv[++i];
    else if (a === '--method') args.method = argv[++i];
    else if (a === '--body') args.body = argv[++i];
    else if (a === '--insert-after') args.insertAfter = argv[++i];
    else if (a === '--write') args.write = true;
  }
  return args;
}

function failJson(message, code) {
  process.stdout.write(JSON.stringify({ ok: false, error: message }) + '\n');
  process.exit(code || 1);
}

const args = parseArgs(process.argv.slice(2));
if (!args.file || !args.method || !args.body) {
  failJson('missing required option --file/--method/--body');
}
if (!fs.existsSync(args.file)) failJson('file not found: ' + args.file);
if (!fs.existsSync(args.body)) failJson('body file not found: ' + args.body);

const bodySource = fs.readFileSync(args.body, 'utf8').trim();
if (!bodySource) failJson('body is empty');

const nameEscaped = args.method.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const bodyPattern = new RegExp('^(async\\s+)?' + nameEscaped + '\\s*\\(');
if (!bodyPattern.test(bodySource)) {
  failJson(
    "body must be a single method starting with '" + args.method + "(' or 'async " +
    args.method + "(' (got: " + JSON.stringify(bodySource.slice(0, 40)) + '...)'
  );
}

const source = fs.readFileSync(args.file, 'utf8');
const scriptKind = args.file.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
const sourceFile = ts.createSourceFile(args.file, source, ts.ScriptTarget.Latest, true, scriptKind);

function findActionsObject(root) {
  let found = null;
  function visit(n) {
    if (found) return;
    if (
      ts.isCallExpression(n) &&
      ts.isIdentifier(n.expression) &&
      n.expression.text === 'defineStore'
    ) {
      const optionsArg = n.arguments[n.arguments.length - 1];
      if (optionsArg && ts.isObjectLiteralExpression(optionsArg)) {
        for (const prop of optionsArg.properties) {
          if (
            ts.isPropertyAssignment(prop) &&
            ts.isIdentifier(prop.name) &&
            prop.name.text === 'actions' &&
            ts.isObjectLiteralExpression(prop.initializer)
          ) {
            found = prop.initializer;
            return;
          }
        }
      }
    }
    ts.forEachChild(n, visit);
  }
  visit(root);
  return found;
}

const actionsObj = findActionsObject(sourceFile);
if (!actionsObj) {
  failJson(
    'no defineStore(...) with an actions: { ... } object literal found in file ' +
    '(this tool only supports Options-API Pinia stores for now)'
  );
}

function findMethods(objLit, name) {
  return objLit.properties.filter(function (p) {
    return ts.isMethodDeclaration(p) && ts.isIdentifier(p.name) && p.name.text === name;
  });
}

const matches = findMethods(actionsObj, args.method);
if (matches.length > 1) {
  failJson("method '" + args.method + "' is ambiguous (" + matches.length + ' definitions found)');
}

function indentOf(node) {
  const start = node.getStart(sourceFile);
  const lc = sourceFile.getLineAndCharacterOfPosition(start);
  return ' '.repeat(lc.character);
}

// Mirrors ast_patch_ruby.rb's reindent: prefix every line with `indent`
// while preserving each line's own relative whitespace, except line 0 on a
// replace (it already sits at the right column via untouched source text).
function reindent(src, indent, skipFirst) {
  const lines = src.split('\n');
  return lines
    .map(function (l, i) {
      if (skipFirst && i === 0) return l;
      return l.trim() === '' ? '' : indent + l;
    })
    .join('\n');
}

let action;
let newText;
let start;
let end;

if (matches.length === 0) {
  const methodProps = actionsObj.properties.filter(function (p) {
    return ts.isMethodDeclaration(p);
  });
  let anchor = null;
  if (args.insertAfter) {
    const found = findMethods(actionsObj, args.insertAfter);
    if (found.length === 0) failJson("--insert-after target '" + args.insertAfter + "' not found");
    anchor = found[found.length - 1];
  } else if (methodProps.length) {
    anchor = methodProps[methodProps.length - 1];
  }

  if (anchor) {
    const indent = indentOf(anchor);
    // Leading comma unconditionally: anchor.getEnd() lands right after its
    // closing `}`, BEFORE any pre-existing trailing comma (if the source
    // has one) or the closing brace (if it doesn't) — inserting ",\n\n<new>"
    // right there is valid either way: it supplies the separator anchor
    // needs, and any comma that already followed anchor now correctly
    // trails the newly inserted method instead.
    newText = ',\n\n' + reindent(bodySource, indent, false);
    start = end = anchor.getEnd();
  } else {
    // Empty actions object — insert right after the opening brace instead
    // of before the closing one, so we don't have to reason about the
    // closing brace's own pre-existing indentation (same trick as
    // ast_patch_ruby.rb's default-anchor fix).
    const indent = '        '; // two nesting levels (store object + actions object), 4 spaces each
    newText = '\n' + reindent(bodySource, indent, false) + '\n' + indent.slice(0, -4);
    start = end = actionsObj.getStart(sourceFile) + 1;
  }
  action = 'inserted';
} else {
  const m = matches[0];
  start = m.getStart(sourceFile);
  end = m.getEnd();
  const indent = indentOf(m);
  newText = reindent(bodySource, indent, true);
  action = 'replaced';
}

const patched = source.slice(0, start) + newText + source.slice(end);

// safety net: never hand back something that doesn't parse
const patchedFile = ts.createSourceFile(args.file, patched, ts.ScriptTarget.Latest, true, scriptKind);
const diagnostics = patchedFile.parseDiagnostics || [];
if (diagnostics.length > 0) {
  failJson('patch produced invalid TypeScript, nothing written: ' + diagnostics[0].messageText, 2);
}

if (args.write) fs.writeFileSync(args.file, patched);

process.stdout.write(
  JSON.stringify({ ok: true, action: action, method: args.method, content: patched }) + '\n'
);
";
var methodBody = $json.methodBody;
var targetFile = $('Normalize Input').first().json.targetFile;
var method = $('Normalize Input').first().json.method;
var insertAfter = $('Normalize Input').first().json.insertAfter;
var container = $('Normalize Input').first().json.container;
var scriptB64 = Buffer.from(AST_PATCH_SRC).toString('base64');
var bodyB64 = Buffer.from(methodBody).toString('base64');
var insertAfterArg = insertAfter ? (" --insert-after " + shq(insertAfter)) : '';
var sh = "mkdir -p tmp/ast_patch && echo '" + scriptB64 + "' | base64 -d > tmp/ast_patch/ast_patch_ts.cjs && echo '" + bodyB64 + "' | base64 -d > tmp/ast_patch/new_action.ts && node tmp/ast_patch/ast_patch_ts.cjs --file " + shq(targetFile) + " --method " + shq(method) + insertAfterArg + " --body tmp/ast_patch/new_action.ts --write";
return [{ json: {
  container: container,
  targetFile: targetFile,
  method: method,
  dockerBridgePayload: { container: container, args: ['sh', '-c', sh] }
} }];

var resp = $input.first().json;
var targetFile = $('Build Patch Command').first().json.targetFile;
var method = $('Build Patch Command').first().json.method;
var parsed = null;
var parseError = null;
try { parsed = JSON.parse(resp.stdout); } catch (e) { parseError = e.message; }
var ok = resp.exitCode === 0 && parsed && parsed.ok === true;
return [{ json: {
  filesWritten: ok ? 1 : 0,
  generatedFiles: ok ? [{ path: targetFile, content: parsed.content, language: 'typescript' }] : [],
  action: (parsed && parsed.action) ? parsed.action : null,
  method: method,
  error: ok ? null : ((parsed && parsed.error) ? parsed.error : (parseError || resp.stderr || ('docker-bridge exec failed, exitCode ' + resp.exitCode))),
  summary: ok ? ('1 fichier patche (' + parsed.action + ' ' + method + ')') : '0 fichier patche'
} }];

return [{ json: {
  filesWritten: 0,
  generatedFiles: [],
  error: $json.reason,
  summary: '0 fichier patche - reponse qwen invalide'
} }];
